import { AlertCircle, X } from 'lucide-react';
import { Children, isValidElement, useId, type HTMLAttributes, type ReactNode, type Ref } from 'react';
import { cn } from '../../utils/cn';
import { FILE_ICON, fileExtension, fileKind, formatBytes } from './file-kind';
import { thumbnailVariants } from './thumbnail.variants';

export type ThumbnailStatus = 'idle' | 'uploading' | 'done' | 'error';

export interface ThumbnailLabels {
  /** Remove button name; receives the file name. */
  remove: (name: string) => string;
  /** Progress bar name; receives the file name. */
  uploading: (name: string) => string;
  /** Default error text when `error` is `true`. */
  error: string;
  /** Retry action text. */
  retry: string;
}

const DEFAULT_LABELS: ThumbnailLabels = {
  remove: (name) => `Remove ${name}`,
  uploading: (name) => `Uploading ${name}`,
  error: 'Upload failed',
  retry: 'Retry',
};

export interface ThumbnailProps extends Omit<HTMLAttributes<HTMLElement>, 'className' | 'children'> {
  className?: string;
  ref?: Ref<HTMLElement>;
  /** File name; the caption and the accessible name. */
  name: string;
  /** Size in bytes, shown as "2.4 MB". */
  size?: number;
  /** MIME type; picks the icon (falls back to the extension). */
  type?: string;
  /** Image preview URL. Without it the file-type icon shows. */
  src?: string;
  /** Custom preview (replaces image and icon). */
  preview?: ReactNode;
  /** Upload progress 0–100: shows the shimmer and a progress bar. `null` = indeterminate. */
  progress?: number | null;
  /** Error state; a string replaces the default message. */
  error?: boolean | string;
  /** Shows the remove button. */
  onRemove?: () => void;
  /** Shows a retry action in the error state. */
  onRetry?: () => void;
  /** BCP 47 locale for the size. */
  locale?: string;
  /** Built-in strings (English defaults). */
  labels?: Partial<ThumbnailLabels>;
}

/**
 * File or image preview tile (a `<figure>` captioned with name and size): image or file-type
 * icon, upload progress with a reduced-motion-safe shimmer, error state and a remove button.
 */
export function Thumbnail({
  name,
  size,
  type,
  src,
  preview,
  progress,
  error,
  onRemove,
  onRetry,
  locale,
  labels: labelsProp,
  className,
  ...props
}: ThumbnailProps) {
  const labels = { ...DEFAULT_LABELS, ...labelsProp };
  const nameId = useId();
  const uploading = progress !== undefined && !error && (progress === null || progress < 100);
  const status: ThumbnailStatus = error ? 'error' : uploading ? 'uploading' : progress !== undefined ? 'done' : 'idle';
  const s = thumbnailVariants({ status });
  const kind = fileKind(name, type);
  const Icon = error ? AlertCircle : FILE_ICON[kind];
  const ext = fileExtension(name);
  const errorText = typeof error === 'string' ? error : labels.error;
  const pct = progress == null ? undefined : Math.max(0, Math.min(100, Math.round(progress)));

  return (
    <figure aria-labelledby={nameId} className={cn(s.root(), className)} data-status={status} aria-busy={uploading || undefined} {...props}>
      <div className={s.preview()}>
        {preview ?? (src && !error ? <img src={src} alt="" className={s.image()} /> : <Icon size={26} strokeWidth={1.6} aria-hidden className={s.icon()} />)}
        {!src && !preview && !error && ext && (
          <span aria-hidden className={s.ext()}>
            {ext}
          </span>
        )}
        {uploading && <span aria-hidden className={s.shimmer()} />}
        {uploading && (
          <div
            role="progressbar"
            aria-label={labels.uploading(name)}
            aria-valuemin={0}
            aria-valuemax={100}
            aria-valuenow={pct}
            className={s.progress()}
          >
            <span className={cn(s.progressBar(), pct === undefined && 'w-2/5 animate-pulse motion-reduce:animate-none')} style={pct === undefined ? undefined : { width: `${pct}%` }} />
          </div>
        )}
      </div>
      <figcaption className={s.caption()}>
        <span id={nameId} className={s.name()} title={name}>
          {name}
        </span>
        <span className={s.meta()}>
          {error ? (
            <>
              {errorText}
              {onRetry && (
                <>
                  {' · '}
                  <button type="button" onClick={onRetry} className={s.retry()}>
                    {labels.retry}
                  </button>
                </>
              )}
            </>
          ) : uploading && pct !== undefined ? (
            `${pct}%${size !== undefined ? ` · ${formatBytes(size, locale)}` : ''}`
          ) : size !== undefined ? (
            formatBytes(size, locale)
          ) : (
            (ext ?? '')
          )}
        </span>
      </figcaption>
      {onRemove && (
        <button type="button" aria-label={labels.remove(name)} onClick={onRemove} className={s.remove()}>
          <X size={13} strokeWidth={2.2} aria-hidden />
        </button>
      )}
    </figure>
  );
}

export interface ThumbnailListProps extends Omit<HTMLAttributes<HTMLUListElement>, 'className'> {
  className?: string;
  ref?: Ref<HTMLUListElement>;
  children?: ReactNode;
}

/** Wrapping list of thumbnails (each child becomes a list item). Label it with `aria-label`. */
export function ThumbnailList({ className, children, ...props }: ThumbnailListProps) {
  const s = thumbnailVariants();
  return (
    <ul className={cn(s.list(), className)} {...props}>
      {Children.toArray(children)
        .filter(isValidElement)
        .map((child) => (
          <li key={child.key}>{child}</li>
        ))}
    </ul>
  );
}

import { File, FileArchive, FileAudio, FileCode, FileImage, FileSpreadsheet, FileText, FileVideo, type LucideIcon } from 'lucide-react';

export type FileKind = 'image' | 'video' | 'audio' | 'archive' | 'code' | 'spreadsheet' | 'document' | 'file';

const EXT: Record<string, FileKind> = {
  png: 'image', jpg: 'image', jpeg: 'image', gif: 'image', webp: 'image', svg: 'image', avif: 'image',
  mp4: 'video', mov: 'video', webm: 'video',
  mp3: 'audio', wav: 'audio', ogg: 'audio', flac: 'audio',
  zip: 'archive', gz: 'archive', tar: 'archive', tgz: 'archive', '7z': 'archive', rar: 'archive',
  js: 'code', ts: 'code', tsx: 'code', jsx: 'code', json: 'code', yaml: 'code', yml: 'code', py: 'code', sql: 'code', sh: 'code',
  csv: 'spreadsheet', xlsx: 'spreadsheet', xls: 'spreadsheet', parquet: 'spreadsheet', tsv: 'spreadsheet',
  pdf: 'document', doc: 'document', docx: 'document', md: 'document', txt: 'document',
};

/** Kind of a file from its MIME type, falling back to the extension of its name. */
export function fileKind(name: string, type?: string): FileKind {
  const major = type?.split('/')[0];
  if (major === 'image' || major === 'video' || major === 'audio') return major;
  const ext = name.includes('.') ? name.split('.').pop()?.toLowerCase() : undefined;
  return (ext && EXT[ext]) || 'file';
}

/** File extension shown as a tag ("PDF"), or undefined. */
export function fileExtension(name: string) {
  return name.includes('.') ? name.split('.').pop()?.toUpperCase() : undefined;
}

export const FILE_ICON: Record<FileKind, LucideIcon> = {
  image: FileImage,
  video: FileVideo,
  audio: FileAudio,
  archive: FileArchive,
  code: FileCode,
  spreadsheet: FileSpreadsheet,
  document: FileText,
  file: File,
};

/** "2.4 MB" style size with binary multiples. */
export function formatBytes(bytes: number, locale?: string) {
  const units = ['B', 'KB', 'MB', 'GB', 'TB'];
  let value = bytes;
  let i = 0;
  while (value >= 1024 && i < units.length - 1) {
    value /= 1024;
    i++;
  }
  const digits = i === 0 || value >= 10 ? 0 : 1;
  return `${new Intl.NumberFormat(locale, { maximumFractionDigits: digits }).format(value)} ${units[i]}`;
}

export { Thumbnail, ThumbnailList, type ThumbnailProps, type ThumbnailListProps, type ThumbnailStatus, type ThumbnailLabels } from './Thumbnail';
export { fileKind, formatBytes, type FileKind } from './file-kind';
export { thumbnailVariants, type ThumbnailVariantProps } from './thumbnail.variants';
export { doc as thumbnailDoc } from './Thumbnail.doc';

import { tv, type VariantProps } from '../../utils/tv';

export const thumbnailVariants = tv({
  slots: {
    root: 'group relative m-0 flex w-36 flex-col overflow-hidden rounded-lg border bg-card shadow-sm',
    preview: 'relative grid aspect-[4/3] place-items-center overflow-hidden bg-secondary/60',
    image: 'size-full object-cover',
    icon: 'text-muted-foreground',
    ext: 'absolute start-2 bottom-2 rounded-[4px] bg-card px-1 font-mono text-[9.5px] font-semibold tracking-wide text-muted-foreground',
    shimmer: 'pointer-events-none absolute inset-0 animate-pulse bg-foreground/6 motion-reduce:animate-none',
    caption: 'grid gap-0.5 px-2.5 py-2 text-start',
    name: 'truncate text-[12.5px] font-medium text-foreground',
    meta: 'truncate font-mono text-[10.5px] text-muted-foreground',
    progress: 'absolute inset-x-0 bottom-0 h-1 bg-secondary',
    progressBar: 'block h-full bg-primary transition-[width] duration-200 motion-reduce:transition-none',
    remove: [
      'absolute end-1.5 top-1.5 grid size-6 place-items-center rounded-md border border-border bg-card/90 text-muted-foreground shadow-sm transition-colors',
      'hover:bg-secondary hover:text-foreground',
      'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-focus-ring',
    ],
    retry: 'underline underline-offset-2 hover:text-foreground focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-focus-ring rounded-sm',
    list: 'm-0 flex list-none flex-wrap gap-3 p-0',
  },
  variants: {
    status: {
      idle: { root: 'border-border' },
      uploading: { root: 'border-border' },
      done: { root: 'border-border' },
      error: { root: 'border-destructive/50', preview: 'bg-destructive/10', icon: 'text-destructive-text', meta: 'text-destructive-text' },
    },
  },
  defaultVariants: { status: 'idle' },
});

export type ThumbnailVariantProps = VariantProps<typeof thumbnailVariants>;

import type { ComponentDoc } from '../../doc';

export const doc: ComponentDoc = {
  name: 'Thumbnail',
  group: 'Display',
  status: 'beta',
  description:
    'File or image preview tile: image or file-type icon with extension tag, name and size caption, upload progress (progressbar + shimmer that holds still under reduced motion), error state with retry, and a remove button. ThumbnailList lays tiles out as a wrapping list.',
  pattern: 'figure',
  keyboard: [
    ['Tab', 'Moves to the remove button (and retry, in the error state) of each tile'],
    ['Enter / Space', 'Activates remove or retry'],
  ],
  tokens: ['card', 'border', 'secondary', 'muted-foreground', 'foreground', 'primary', 'destructive', 'destructive-text', 'focus-ring'],
};

/**
 * Component documentation contract. Every component folder exports a `*.doc.ts`
 * with this shape; the registry build and the docs site read it.
 */
export interface ComponentDoc {
  /** Public component name, e.g. "Button". */
  name: string;
  /** Inventory group, e.g. "Actions", "Forms", "Overlays". */
  group: 'Actions' | 'Forms' | 'Overlays' | 'Navigation' | 'Display' | 'Feedback' | 'Layout' | 'Theme';
  /** Lifecycle badge. */
  status: 'stable' | 'beta' | 'experimental';
  description: string;
  /** Headless primitive it is built on, if any (e.g. "@base-ui/react/dialog"). */
  primitive?: string;
  /** WAI-ARIA pattern the a11y contract test checks. */
  pattern?: string;
  /** Keyboard contract: key → behaviour. Each row is covered by a test. */
  keyboard?: Array<[key: string, behaviour: string]>;
  /** Tokens the component reads (for the theming docs). */
  tokens?: string[];
}
